exercises.solution:
play <- function(start, goal, p) {
  money <- start
  while (money > 0 && money < goal) {
    money <- money + if (runif(1) < p) 1 else -1
  }
  money == goal
}
set.seed(2)
p_win <- mean(replicate(2000, play(10, 20, 0.5)))

set.seed(5)
